<?php
namespace App\Controllers\Gestion;use App\Core\Controller;use App\Core\Request;use App\Core\Session;use App\Models\FormulaAdmin;use App\Models\Catalog;use App\Services\FormulaAdminService;use Throwable;
class FormulaAdminController extends Controller{public function index(Request $r):void{$m=new FormulaAdmin();$c=new Catalog();$this->view('formulas/index',['title'=>'Fórmulas médicas','formulas'=>$m->all(active_environment_id()),'categories'=>$m->categories(),'variableTypes'=>$m->variableTypes(),'variableOrigins'=>$m->variableOrigins(),'units'=>$c->measurementUnits(),'species'=>$c->species(),'success'=>Session::pullFlash('success'),'error'=>Session::pullFlash('error')]);}public function store(Request $r):void{$this->go($r,fn()=>(new FormulaAdminService())->create($r->all(),active_environment_id(),auth_id()),'/formulas','Fórmula creada.');}public function version(Request $r,string $id):void{$this->go($r,fn()=>(new FormulaAdminService())->addVersion((int)$id,$r->all(),active_environment_id(),auth_id()),'/formulas','Nueva versión creada.');}public function publish(Request $r,string $id):void{$this->go($r,fn()=>(new FormulaAdminService())->publish((int)$id,active_environment_id(),auth_id()),'/formulas','Versión publicada.');}private function go(Request $r,callable $f,string $b,string $ok):void{if(!Session::validateCsrf($r->input('_token'))){http_response_code(419);return;}try{$f();Session::flash('success',$ok);}catch(Throwable $e){Session::flash('error',$e->getMessage());}$this->redirect($b);}}
